            cap, uv: new Float32Array(cap * 2), conic: new Float32Array(cap * 3), cov: new Float32Array(cap * 3), depth: new Float32Array(cap), radius: new Int32Array(cap),
            rgb: new Float32Array(cap * 3), opac: new Float32Array(cap), t: new Float32Array(cap * 3), clampX: new Uint8Array(cap), clampY: new Uint8Array(cap),
            T: new Float32Array(cap * 6), Sig: new Float32Array(cap * 6), Rm: new Float32Array(cap * 9), s: new Float32Array(cap * 3), qn: new Float32Array(cap * 4), ql: new Float32Array(cap),
