            const q0 = quat[i * 4], q1 = quat[i * 4 + 1], q2 = quat[i * 4 + 2], q3 = quat[i * 4 + 3], ql = Math.sqrt(q0 * q0 + q1 * q1 + q2 * q2 + q3 * q3) || 1;
            const w = q0 / ql, x = q1 / ql, y = q2 / ql, z = q3 / ql;
