// ═════════════════════════════════ 预览用的绘图小工具（只在浏览器里调用） ═════════════════════════════════
const P15V = (() => {
    const C = LM.C, F = LM.FONT, offs = [];
    function imgCanvas(rgb, W, H, slot) {
        let cv = offs[slot]; if (!cv) cv = offs[slot] = document.createElement('canvas');
        if (cv.width !== W || cv.height !== H) { cv.width = W; cv.height = H; }
        const cx = cv.getContext('2d'), im = cx.createImageData(W, H), d = im.data;
        for (let i = 0; i < W * H; i++) { d[i * 4] = rgb[i * 3] * 255; d[i * 4 + 1] = rgb[i * 3 + 1] * 255; d[i * 4 + 2] = rgb[i * 3 + 2] * 255; d[i * 4 + 3] = 255; }
        cx.putImageData(im, 0, 0); return cv;
    }
    /** 几张小图并排（像素化 = 真实分辨率）：items = [{ rgb, W, H, label, sub, color, outline, draw(ctx, cell) }]。返回每格的位置（存进 S 给 probe / pick 用） */
    function panels(c, items, o) {
        o = o || {};
        const { ctx, w, h } = PL.draw.ctx(c, { bg: '#050608' });
        const n = items.length, cols = o.cols || n, rows = Math.ceil(n / cols), gap = o.gap ?? 8, lab = o.lab ?? (items.some((it) => it.sub) ? 31 : 17), top = o.title ? 20 : 5;
        const cell = Math.min((w - gap * (cols - 1) - 10) / cols, (h - top - rows * lab - (rows - 1) * gap - 3) / rows);
        const x0 = (w - (cols * cell + (cols - 1) * gap)) / 2, cells = [];
        if (o.title) { ctx.font = F(11, true); ctx.fillStyle = C.text; ctx.textAlign = 'left'; ctx.textBaseline = 'top'; ctx.fillText(o.title, o.titleX ?? 6, 4); }
        items.forEach((it, k) => {
            const x = x0 + (k % cols) * (cell + gap), y = top + Math.floor(k / cols) * (cell + lab + gap);
            if (it.rgb) { ctx.imageSmoothingEnabled = !!it.smooth; ctx.drawImage(imgCanvas(it.rgb, it.W, it.H, (o.slot || 0) + k), x, y, cell, cell * it.H / it.W); ctx.imageSmoothingEnabled = true; }
            else { ctx.fillStyle = '#0c0f13'; ctx.fillRect(x, y, cell, cell); }
            ctx.strokeStyle = it.outline || '#232a33'; ctx.lineWidth = it.outline ? 2 : 1; ctx.strokeRect(x - 1, y - 1, cell + 2, cell + 2);
            const cl = { x, y, s: cell, W: it.W, H: it.H, k: cell / it.W, X: (u) => x + u / it.W * cell, Y: (v) => y + v / it.H * cell };
            if (it.draw) { ctx.save(); ctx.beginPath(); ctx.rect(x, y, cell, cell); ctx.clip(); it.draw(ctx, cl); ctx.restore(); }
            ctx.textAlign = 'center'; ctx.textBaseline = 'top';
            if (it.label) { ctx.font = F(11, true); ctx.fillStyle = it.color || C.text; ctx.fillText(it.label, x + cell / 2, y + cell + 3); }
            if (it.sub) { ctx.font = F(11); ctx.fillStyle = C.gray; ctx.fillText(it.sub, x + cell / 2, y + cell + 17); }
            cells.push(cl);
        });
        return { ctx, cells, w, h };
    }
    /** probe / pick：设计坐标 → { k: 第几格, u, v: 格内的图像像素坐标 } */
    function hitCells(cells, info) {
        if (!cells || !info) return null;
        for (let k = 0; k < cells.length; k++) { const q = cells[k]; if (info.dx >= q.x && info.dx < q.x + q.s && info.dy >= q.y && info.dy < q.y + q.s * q.H / q.W) return { k, u: (info.dx - q.x) / q.k, v: (info.dy - q.y) / q.k }; }
        return null;
    }
    /** 2D 协方差 [[A, B], [B, Cc]]（像素²）的 k·σ 椭圆；cl = panels 返回的格子（像素 → 设计坐标） */
    function ellipse(ctx, cl, u, v, A, B, Cc, k, color, width, dash) {
        const tr = (A + Cc) / 2, df = Math.sqrt(Math.max(0, (A - Cc) * (A - Cc) / 4 + B * B)), l1 = tr + df, l2 = Math.max(1e-9, tr - df), th = 0.5 * Math.atan2(2 * B, A - Cc);
        ctx.strokeStyle = color; ctx.lineWidth = width || 1.5; ctx.setLineDash(dash || []);
        ctx.beginPath(); ctx.ellipse(cl.X(u), cl.Y(v), k * Math.sqrt(l1) * cl.k, k * Math.sqrt(l2) * cl.k, th, 0, 2 * Math.PI); ctx.stroke(); ctx.setLineDash([]);
    }
    function mark(ctx, x, y, color, r) {
        r = r || 5;
        [['#000', 3.5], [color || C.yellow, 1.6]].forEach(([c, lw]) => { ctx.strokeStyle = c; ctx.lineWidth = lw; ctx.beginPath(); ctx.moveTo(x - r, y); ctx.lineTo(x + r, y); ctx.moveTo(x, y - r); ctx.lineTo(x, y + r); ctx.stroke(); });
    }
    /** 误差图：三通道平均 |a − b| × gain → inferno 伪彩色 */
    function errRGB(a, b, n, gain) {
        const out = new Float32Array(n * 3), rgb = [0, 0, 0];
        for (let i = 0; i < n; i++) { const e = (Math.abs(a[i * 3] - b[i * 3]) + Math.abs(a[i * 3 + 1] - b[i * 3 + 1]) + Math.abs(a[i * 3 + 2] - b[i * 3 + 2])) / 3 * gain; PL.cmap.inferno(Math.min(1, e), rgb); out[i * 3] = rgb[0] / 255; out[i * 3 + 1] = rgb[1] / 255; out[i * 3 + 2] = rgb[2] / 255; }
        return out;
    }
    /** 带深色底的文字标签 */
    function tag(ctx, s, x, y, color, align) {
        ctx.font = F(11); ctx.textAlign = align || 'left'; ctx.textBaseline = 'top';
        const tw = ctx.measureText(s).width, x0 = align === 'right' ? x - tw : align === 'center' ? x - tw / 2 : x;
        ctx.fillStyle = 'rgba(5,7,10,0.72)'; ctx.fillRect(x0 - 2, y - 1, tw + 4, 15); ctx.fillStyle = color || C.text; ctx.fillText(s, x, y);
    }
    /** 一组数值的直方图（bins 个桶，返回计数）——给 PL.draw.plot 画柱 */
    function hist(vals, lo, hi, bins) { const h = new Array(bins).fill(0); vals.forEach((v) => { const k = Math.floor((v - lo) / (hi - lo) * bins); if (k >= 0 && k < bins) h[k]++; }); return h; }
    const fmtMs = (ms) => (ms >= 1000 ? (ms / 1000).toFixed(2) + ' s' : ms >= 10 ? ms.toFixed(0) + ' ms' : ms.toFixed(2) + ' ms');
    return { imgCanvas, panels, hitCells, ellipse, mark, errRGB, tag, hist, fmtMs };
})();

