                    const ts = performance.now();
                    R.acc += P15.nerfStep(R.net, R.opt, S.rays, R.rand, P15T.NL_B, P15T.NL_LR * Math.pow(0.1, R.it / P15T.NL_CAP)); R.nAcc++;
