                        S.cams.train.forEach((k, i) => { const u = k.C.map((x, a) => x - P15.CENTER[a]), cs = P15.dot3(v, u) / (Math.hypot(...v) * Math.hypot(...u)); if (cs > bd) { bd = cs; best = i; } });
